def simulate_balance_lcol(items, available_height, avoid_widows=True):
    # Suppose items are to be rendered in lCol
    # Each item has height
    rendered = []
    current_h = 0
    trimmed_result = None

    for i, item in enumerate(items):
        is_last = (i == len(items) - 1)

        # Check height
        if item.type == 'p':
            line_h = 22
            para_margin = 7
            item_h = len(item.lines) * line_h + para_margin
            if current_h + item_h > available_height and len(rendered) > 0:
                # Find how many lines fit
                space_left = available_height - current_h - para_margin
                fit_lines = max(0, space_left // line_h)

                # Check widow constraint: if fit_lines == 1 and avoid_widows, fit_lines = 0!
                if fit_lines < 2 and avoid_widows:
                    fit_lines = 0

                # Check if preceding element in rendered was a heading!
                if len(rendered) > 0 and rendered[-1].type == 'h' and fit_lines < 2:
                    fit_lines = 0

                if fit_lines > 0:
                    rendered.append(DOMNode('P', 'p-cut', lines_count=fit_lines, is_cut=True))
                    trimmed_result = {
                        'trimmed_token': item.text,
                        'remaining_lines': item.lines[fit_lines:],
                        'unrendered': [it.text for it in items[i+1:]]
                    }
                else:
                    trimmed_result = {
                        'trimmed_token': item.text,
                        'remaining_lines': item.lines,
                        'unrendered': [it.text for it in items[i+1:]]
                    }
                break
            else:
                rendered.append(DOMNode('P', 'p-cut' if item.is_cut else 'p-end', lines_count=len(item.lines), is_cut=item.is_cut))
                current_h += item_h
        elif item.type == 'h':
            h_height = 40
            if current_h + h_height > available_height and len(rendered) > 0:
                trimmed_result = {
                    'trimmed_token': item.text,
                    'remaining_lines': None,
                    'unrendered': [it.text for it in items[i:]]
                }
                break
            else:
                rendered.append(DOMNode('DIV', 'title-level-4', text=item.text))
                current_h += h_height

    # Now run cascading cleanColumnTail on rendered!
    rb = clean_column_tail(rendered, avoid_widows)
    if rb:
        # Prepend rolled back items to trimmed_result unrendered
        if not trimmed_result:
            trimmed_result = {'trimmed_token': None, 'remaining_lines': None, 'unrendered': []}
        for r in rb:
            if r.tagName == 'DIV':
                trimmed_result['unrendered'].insert(0, r.text)
            elif r.tagName == 'P':
                trimmed_result['unrendered'].insert(0, f"P({r.linesCount} lines)")

    return rendered, trimmed_result

